// Inner capsule (heimdall-job-v1) validation and bucket padding.
import { createHash } from 'node:crypto';
export const BUCKETS = [4, 16, 64, 256].map((k) => k * 1024);
export const SERVER_CEILINGS = { max_tokens: 4096, max_cost_units: 10, timeout_ms: 30000 };
export const OPERATIONS = new Set(['echo']); // Phase 1: bounded deterministic echo only
const FORBIDDEN = ['device_id', 'account_id', 'doc_hash', 'witness_id', 'conversation_id', 'timestamp', 'pseudonym'];
const enc = new TextEncoder(), dec = new TextDecoder();

export function bucketFor(n) { return BUCKETS.find((b) => b >= n) ?? null; }

// Body layout: u32 payloadLen | payload JSON | zero pad. Total body length chosen by caller.
export function padBody(obj, targetLen) {
  const p = enc.encode(JSON.stringify(obj));
  if (4 + p.length > targetLen) throw new Error('capsule exceeds bucket');
  const out = new Uint8Array(targetLen);
  new DataView(out.buffer).setUint32(0, p.length);
  out.set(p, 4);
  return out;
}
export function unpadBody(bytes) {
  if (bytes.length < 4) throw new Error('short');
  const n = new DataView(bytes.buffer, bytes.byteOffset).getUint32(0);
  if (n > bytes.length - 4) throw new Error('bad length');
  return JSON.parse(dec.decode(bytes.subarray(4, 4 + n)));
}

export function validateCapsule(c) {
  const bad = (m) => { const e = new Error(m); e.code = 'invalid_capsule'; throw e; };
  if (!c || typeof c !== 'object') bad('not object');
  if (c.version !== 'heimdall-job-v1') bad('version');
  if (typeof c.job_nonce !== 'string' || !/^[A-Za-z0-9_-]{16,64}$/.test(c.job_nonce)) bad('nonce');
  if (!OPERATIONS.has(c.operation)) bad('operation');
  if (!['symbolic', 'public-query', 'explicitly-sensitive'].includes(c.disclosure)) bad('disclosure');
  for (const k of FORBIDDEN) if (k in c) bad('forbidden field ' + k);
  const b = c.budget ?? {};
  for (const k of Object.keys(SERVER_CEILINGS)) if (!Number.isFinite(b[k]) || b[k] < 0) bad('budget');
  if (typeof c.input !== 'object' || c.input === null) bad('input');
  return { ...c, budget: Object.fromEntries(Object.entries(SERVER_CEILINGS).map(([k, v]) => [k, Math.min(v, b[k])])) };
}
export const digest = (s) => createHash('sha256').update(s).digest('hex');
