const MAX_ENVELOPE = BUCKETS.at(-1) + 512;
const IDEMP_TTL_MS = 3600_000;

export async function startGateway({ port = 0, keyId = 1, allowedRelayToken, observe } = {}) {
  const config = new KeyConfig(keyId);
  const server = new Server(config);
  const keyConfig = await server.encodeKeyConfigAsList();
  const seen = new Map(); // job_nonce -> {hash, result, exp}
  let executions = 0;

  async function execute(capsule) {
    const key = capsule.job_nonce, h = digest(JSON.stringify(capsule));
    const now = Date.now();
    for (const [k, v] of seen) if (v.exp < now) seen.delete(k);
    const prior = seen.get(key);
    if (prior) {
      if (prior.hash !== h) return { outcome: 'error', error: 'nonce_conflict' };
      return prior.result;
    }
    executions++;
    const result = { outcome: 'ok', output: { echo: capsule.input }, usage: { tokens: 0, cost_units: 0 } };
    seen.set(key, { hash: h, result, exp: now + IDEMP_TTL_MS });
    return result;
  }

