// Falsification group A: RFC 9458 Appendix A known-answer test against the chosen library.
import test from 'node:test';
import assert from 'node:assert/strict';
import { Server, KeyConfig } from 'ohttp-js';
const hex = (s) => Uint8Array.from(Buffer.from(s.replace(/\s/g, ''), 'hex'));
const toHex = (u) => Buffer.from(u).toString('hex');

const SK = '3c168975674b2fa8e465970b79c8dcf09f1c741626480bd4c6162fc5b6a98e1a';
const CONFIG = '01002031e1f05a740102115220e9af918f738674aec95f54db6e04eb705aae8e79815500080001000100010003';
const REQ = '010020000100014b28f881333e7c164ffc499ad9796f877f4e1051ee6d31bad19dec96c208b4726374e469135906992e1268c594d2a10c695d858c40a026e7965e7d86b83dd440b2c0185204b4d63525';
const BHTTP = '00034745540568747470730b6578616d706c652e636f6d012f';
const RESP_SECRET = '62d87a6ba569ee81014c2641f52bea36';

async function rfcServer() {
  const cfg = new KeyConfig(1);
  const pk = hex(CONFIG).slice(3, 35);
  const pkcs8 = Buffer.concat([Buffer.from('302e020100300506032b656e04220420', 'hex'), Buffer.from(SK, 'hex')]);
  const privateKey = await crypto.subtle.importKey('pkcs8', pkcs8, { name: 'X25519' }, true, ['deriveBits']);
  const publicKey = await crypto.subtle.importKey('raw', pk, { name: 'X25519' }, true, []);
  cfg.keyPair = Promise.resolve({ privateKey, publicKey });
  return new Server(cfg);
}

test('KAT: library encodes the RFC key config byte-for-byte', async () => {
  const s = await rfcServer();
  assert.equal(toHex(await s.encodeKeyConfig()), CONFIG);
});

test('KAT: decapsulating the RFC request yields the RFC binary HTTP message and response secret', async () => {
  const s = await rfcServer();
  const ctx = await s.decodeAndDecapsulate(hex(REQ));
  assert.equal(toHex(ctx.secret), RESP_SECRET);
  const req = ctx.request();
  assert.equal(req.method, 'GET'); assert.equal(req.url, 'https://example.com/');
});
E
