// Signed key-configuration bundle: authenticates gateway keys independently of the relay.
import { sign, verify, generateKeyPairSync } from 'node:crypto';
export const newSigningKey = () => generateKeyPairSync('ed25519');
export function signBundle(privateKey, { version, notBefore, expires, configs }) {
  const body = JSON.stringify({ v: 1, version, notBefore, expires, configs: configs.map((c) => Buffer.from(c).toString('hex')) });
  return { body, sig: sign(null, Buffer.from(body), privateKey).toString('hex') };
}
// state: { lastVersion } persisted locally by the client (rollback protection).
export function openBundle(pinnedPublicKey, bundle, state, now = Date.now()) {
  if (!verify(null, Buffer.from(bundle.body), pinnedPublicKey, Buffer.from(bundle.sig, 'hex'))) throw new Error('bad_signature');
  const b = JSON.parse(bundle.body);
  if (b.v !== 1) throw new Error('bad_format');
  if (now < b.notBefore) throw new Error('not_yet_valid');
  if (now >= b.expires) throw new Error('expired');
  if (b.version < (state.lastVersion ?? 0)) throw new Error('rollback');
  state.lastVersion = b.version;
  return b.configs.map((h) => Uint8Array.from(Buffer.from(h, 'hex')));
}
