// Heimdall security supervisor. Owns the security decision for every outbound call and DELEGATES by call kind
// to specialist guards. Fails closed: a kind with no assigned guard is vetoed. Guards can only tighten, never loosen.
//
// Guard contract (each guard is a plain object):
//   name: string
//   handles(kind): boolean
//   review(call, decision, ctx) -> { allow: boolean, reasons: string[] }       // pre-dispatch; sync or async
//   validateResponse(call, output, ctx) -> { ok: boolean, reasons: string[], output }  // post-dispatch; output is UNTRUSTED
export function createHeimdall({ guards = [], assignments = { reason: 'llm', provider: 'llm', search: 'search', fetch: 'search' } } = {}) {
  const byName = new Map(guards.map((g) => [g.name, g]));
  const assigned = (kind) => byName.get(assignments[kind]);
  return {
    guards: () => [...byName.keys()],
    assignedTo: (kind) => assignments[kind] ?? null,
    async review(call, decision, ctx = {}) {
      if (decision.route === 'blocked' || decision.route === 'unresolved') return { allow: false, reasons: decision.reasons, by: 'compiler' };
      const g = assigned(call.kind);
      if (!g) return { allow: false, reasons: [`no_guard_assigned:${call.kind}`], by: 'heimdall' }; // fail closed
      try {
        const r = await g.review(call, decision, ctx);
        return { allow: r.allow === true, reasons: r.reasons ?? [], by: g.name };
      } catch (e) { return { allow: false, reasons: [`guard_crashed:${g.name}`], by: g.name }; } // fail closed
    },
    async validateResponse(call, output, ctx = {}) {
      const g = assigned(call.kind);
      if (!g) return { ok: false, reasons: [`no_guard_assigned:${call.kind}`], output: null };
      try { const r = await g.validateResponse(call, output, ctx); return { ok: r.ok === true, reasons: r.reasons ?? [], output: r.ok ? r.output : null, by: g.name }; }
      catch { return { ok: false, reasons: [`guard_crashed:${g.name}`], output: null, by: g.name }; }
    },
  };
}
