  return out;
}
export function unpadBody(bytes) {
  if (bytes.length < 4) throw new Error('short');
  const n = new DataView(bytes.buffer, bytes.byteOffset).getUint32(0);
  if (n > bytes.length - 4) throw new Error('bad length');
  return JSON.parse(dec.decode(bytes.subarray(4, 4 + n)));
