import assert from 'node:assert/strict';
import { makeRuntime } from '../src/guards/compat/runtime.js';
import { createLlmGuard } from '../src/guards/mimir.js';
import { createSearchGuard } from '../src/guards/ratatoskr.js';

const strictClone = function (v) { if (this !== undefined && this !== globalThis) throw new TypeError('Illegal invocation'); return structuredClone(v); };
const B = { max_tokens: 100, max_cost_units: 1, timeout_ms: 5000 };

test('guards accept plain data under a strict-this structuredClone (browser behaviour) and still refuse proxies', async () => {
  const rt = makeRuntime({ kind: 'browser', structuredClone: strictClone });
  assert.equal(rt.proofReady, true);
  const m = createLlmGuard({ runtime: rt }); const r = createSearchGuard({ runtime: rt, allowHosts: ['example.org'] });
  const dec = { route: 'remote', reasons: [], capsule: { operation: 'reason', disclosure: 'symbolic', budget: B, input: { q: 'w1' } } };
  assert.equal((await m.review({ kind: 'reason', input: { q: 'w1' }, budget: B }, dec, {})).allow, true);
  assert.equal((await m.review(new Proxy({ kind: 'reason', input: { q: 'w1' }, budget: B }, {}), dec, {})).allow, false);
  const f = await r.review({ kind: 'fetch', url: 'https://example.org/p', budget: B }, { route: 'remote', reasons: [] }, { allowHosts: ['example.org'] });
  assert.equal(f.allow, true, JSON.stringify(f));
